import pytest

from minischema import validate


@pytest.mark.parametrize(
    "value, type_name",
    [
        ({}, "object"),
        ([], "array"),
        ("x", "string"),
        (1, "integer"),
        (1.5, "number"),
        (True, "boolean"),
        (None, "null"),
    ],
)
def test_matching_type_is_valid(value, type_name):
    assert validate(value, {"type": type_name}) == []


@pytest.mark.parametrize(
    "value, type_name",
    [
        (True, "integer"),
        (False, "number"),
        (1.0, "integer"),
        ("1", "integer"),
        (None, "boolean"),
        ([], "object"),
        ({}, "array"),
        (0, "string"),
        (0, "null"),
    ],
)
def test_wrong_type_reports_only_type_error(value, type_name):
    assert validate(value, {"type": type_name, "minimum": 10}) == [
        f"$: expected {type_name}"
    ]


def test_unknown_type_raises():
    with pytest.raises(ValueError):
        validate(1, {"type": "float"})


def test_missing_required_reported_in_required_order():
    schema = {
        "type": "object",
        "required": ["b", "a"],
        "properties": {"a": {"type": "string"}, "b": {"type": "string"}},
    }
    assert validate({}, schema) == [
        "$: missing required property b",
        "$: missing required property a",
    ]


def test_required_errors_precede_property_errors():
    schema = {
        "type": "object",
        "required": ["email"],
        "properties": {"age": {"type": "integer"}, "name": {"type": "string"}},
    }
    data = {"name": 3, "age": "old"}
    assert validate(data, schema) == [
        "$: missing required property email",
        "$.age: expected integer",
        "$.name: expected string",
    ]


def test_property_errors_follow_properties_order():
    schema = {
        "properties": {"z": {"type": "string"}, "a": {"type": "string"}},
    }
    assert validate({"a": 1, "z": 2}, schema) == [
        "$.z: expected string",
        "$.a: expected string",
    ]


